-- CREATE/DEFINE DYNAMIC TABLE with a DATA_METRIC_SCHEDULE
-- https://docs.snowflake.com/en/sql-reference/sql/create-dynamic-table

CREATE OR REPLACE DYNAMIC TABLE dt
TARGET_LAG = '12 hours'
REFRESH_MODE = AUTO
INITIALIZE = ON_CREATE
WAREHOUSE = wh
DATA_METRIC_SCHEDULE = TRIGGER_ON_CHANGES
AS
SELECT 1 AS a;

CREATE DYNAMIC TABLE dt_interval
TARGET_LAG = DOWNSTREAM
WAREHOUSE = wh
DATA_METRIC_SCHEDULE = '60 MINUTE'
AS
SELECT 1 AS a;

DEFINE DYNAMIC TABLE DCM_PROJECT.ANALYTICS.DT_METRIC_SCHEDULE
TARGET_LAG = '1 DAY'
WAREHOUSE = DCM_PROJECT_WH
INITIALIZE = ON_SCHEDULE
DATA_METRIC_SCHEDULE = 'USING CRON 0 0 10-20 * TUE,THU UTC'
AS
SELECT a FROM b;
